#!/usr/bin/env python3
"""Vector sets of the fpalu testbench (WP13).

  python mncore/sim/tb/fpalu/fpalu_vec.py manifest   # rewrite manifest_fixed.txt (vectors_fixed)
  python mncore/sim/tb/fpalu/fpalu_vec.py check      # manifest_fixed.txt is up to date
  python mncore/sim/tb/fpalu/fpalu_vec.py full [--seed N] [--maxerr N] [--fixed] [--rnd0]
      # run tb_fpalu on every file of mncore/sim/vectors/fpalu (generated by vecgen; see
      # mncore/vecgen/FORMAT.md: generate, then --official-expect), or of vectors_fixed
      # (--fixed). --rnd0 builds the units with RND = 0 and skips the r files.

The testbench reads a manifest (one .vec path per line, relative to the repository root) given
with +manifest=. `full` refuses files with disputed= but without expect=official: their expected
values would be the Rust simulator's, not the official emulator's (contract section 5).
"""
import argparse
import os
import shutil
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]
FIXED = ROOT / "mncore" / "sim" / "vectors_fixed" / "fpalu"
FULL = ROOT / "mncore" / "sim" / "vectors" / "fpalu"
MANIFEST = HERE / "manifest_fixed.txt"

if shutil.which("iverilog") is None:
    _oss = Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "oss-cad-suite"
    os.environ["PATH"] = os.pathsep.join([str(_oss / "bin"), str(_oss / "lib"), os.environ.get("PATH", "")])


def header(p):
    with open(p, encoding="utf-8") as f:
        return f.readline()


def manifest_text(d):
    files = sorted(d.glob("*.vec"))
    lines = ["# generated by fpalu_vec.py: vector files of tb_fpalu"]
    lines += [f.relative_to(ROOT).as_posix() for f in files]
    return "\n".join(lines) + "\n", files


def cmd_manifest(_a):
    text, files = manifest_text(FIXED)
    MANIFEST.write_text(text, encoding="utf-8", newline="\n")
    print(f"{MANIFEST.relative_to(ROOT).as_posix()}: {len(files)} files")
    return 0


def cmd_check(_a):
    text, files = manifest_text(FIXED)
    if not MANIFEST.exists() or MANIFEST.read_text(encoding="utf-8") != text:
        print("FAIL manifest_fixed.txt is out of date (run: fpalu_vec.py manifest)")
        return 1
    print(f"PASS manifest_fixed.txt lists the {len(files)} files of vectors_fixed/fpalu")
    return 0


def tb_files():
    files = []
    for raw in (HERE / "files.txt").read_text(encoding="utf-8").splitlines():
        line = raw.split("#", 1)[0].strip()
        if line and not line.split(":", 1)[0] in ("top", "rtl_top", "incdir", "define"):
            files.append(line)
    return files


def cmd_full(a):
    src = FIXED if a.fixed else FULL
    _, files = manifest_text(src)
    if not files:
        print(f"FAIL no vectors in {src} (cd mncore/vecgen; cargo run --release -- fpalu; "
              "cargo run --release -- fpalu --official-expect)")
        return 1
    bad = [f.name for f in files if "disputed=" in header(f) and "expect=official" not in header(f)]
    if bad:
        print(f"FAIL {len(bad)} disputed files without expect=official (run vecgen --official-expect): "
              + " ".join(bad[:8]))
        return 1
    build = HERE / "build"
    build.mkdir(exist_ok=True)
    tag = ("fixed" if a.fixed else "full") + ("_rnd0" if a.rnd0 else "")
    man = build / f"manifest_{tag}.txt"
    man.write_text("\n".join(f.relative_to(ROOT).as_posix() for f in files) + "\n", encoding="utf-8")
    vvp = build / f"{tag}.vvp"
    cmd = ["iverilog", "-g2012", "-Wall", "-Wno-timescale", "-o", str(vvp), "-s", "tb_fpalu"]
    if a.rnd0:
        cmd.append("-Ptb_fpalu.TB_RND=0")
    cmd += tb_files()
    r = subprocess.run(cmd, cwd=ROOT, text=True, capture_output=True)
    if r.returncode:
        print(r.stdout + r.stderr)
        print("FAIL iverilog compile")
        return 1
    r = subprocess.run(["vvp", "-n", str(vvp), f"+manifest={man.relative_to(ROOT).as_posix()}",
                        f"+seed={a.seed}", f"+maxerr={a.maxerr}"], cwd=ROOT, text=True,
                       capture_output=True)
    out = r.stdout + r.stderr
    (build / f"{tag}.log").write_text(out, encoding="utf-8")
    sys.stdout.write(out)
    verdicts = [l for l in r.stdout.splitlines() if l.startswith(("PASS", "FAIL"))]
    return 0 if verdicts and verdicts[-1].startswith("PASS") else 1


def main():
    ap = argparse.ArgumentParser()
    sp = ap.add_subparsers(dest="cmd", required=True)
    sp.add_parser("manifest")
    sp.add_parser("check")
    f = sp.add_parser("full")
    f.add_argument("--seed", type=int, default=1)
    f.add_argument("--maxerr", type=int, default=5)
    f.add_argument("--fixed", action="store_true", help="vectors_fixed instead of the generated set")
    f.add_argument("--rnd0", action="store_true", help="units built with RND = 0; r files skipped")
    a = ap.parse_args()
    return {"manifest": cmd_manifest, "check": cmd_check, "full": cmd_full}[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
